from typing import Final

import pytest

from app.worker.coverage_pure import (
    CoverageData,
    FileCoverage,
    mark_covered,
    parse_coverage_xml,
)
from app.worker.violation_pure import Violation


def _xml(classes: str) -> bytes:
    return f"""<?xml version="1.0" ?>
<coverage version="7.6">
  <!-- Generated by coverage.py -->
  <sources><source></source><source>.</source></sources>
  <packages><package name="."><classes>{classes}</classes></package></packages>
</coverage>""".encode()


MOD: Final = """<class name="m.py" filename="m.py"><lines>
<line number="1" hits="1"/><line number="3" hits="0"/>
</lines></class>"""


def test_parse_reads_measured_and_executed_lines() -> None:
    cov = parse_coverage_xml(_xml(MOD))
    assert cov == CoverageData({"m.py": FileCoverage(frozenset({1, 3}), frozenset({1}))})


def test_parse_merges_classes_of_same_file_and_normalizes_path() -> None:
    xml = _xml(
        '<class filename="./pkg/a.py"><lines><line number="2" hits="0"/></lines></class>'
        '<class filename="pkg/a.py"><lines><line number="2" hits="3"/></lines></class>'
    )
    cov = parse_coverage_xml(xml)
    assert cov is not None
    assert cov.files["pkg/a.py"] == FileCoverage(frozenset({2}), frozenset({2}))


def test_parse_file_without_lines() -> None:
    cov = parse_coverage_xml(_xml('<class filename="empty.py"><lines/></class>'))
    assert cov is not None and cov.files["empty.py"] == FileCoverage(frozenset(), frozenset())


@pytest.mark.parametrize(
    "data",
    [
        b"",
        b"not xml",
        b"<coverage><packages>",  # 잘림
        b"<report/>",  # 다른 형식
        _xml('<class name="x"><lines/></class>'),  # filename 없음
        _xml('<class filename="a.py"><lines><line number="x" hits="1"/></lines></class>'),
        _xml('<class filename="a.py"><lines><line number="1"/></lines></class>'),
        _xml('<class filename="a.py"><lines><line number="0" hits="1"/></lines></class>'),
        _xml('<class filename="a.py"><lines><line number="1" hits="-1"/></lines></class>'),
        # DTD·엔티티 (billion laughs, 외부 엔티티)
        b'<?xml version="1.0"?><!DOCTYPE c [<!ENTITY a "aaaa">]><coverage>&a;</coverage>',
        b'<?xml version="1.0"?><!DOCTYPE c [<!ENTITY x SYSTEM "file:///etc/passwd">]>'
        b"<coverage>&x;</coverage>",
        b'<?xml version="1.0"?><!DOCTYPE coverage><coverage/>',
    ],
    ids=[
        "empty",
        "garbage",
        "truncated",
        "other-root",
        "no-filename",
        "bad-number",
        "no-hits",
        "line-zero",
        "negative-hits",
        "entity",
        "external-entity",
        "doctype",
    ],
)
def test_parse_rejects_broken_or_unsafe_xml(data: bytes) -> None:
    assert parse_coverage_xml(data) is None


def test_parse_size_limit_boundary() -> None:
    data = _xml(MOD)
    assert parse_coverage_xml(data, max_bytes=len(data)) is not None
    assert parse_coverage_xml(data, max_bytes=len(data) - 1) is None


SOURCE: Final = '''"""doc."""
import functools


@functools.lru_cache
def f(a,
      b):
    x = (a +
         42)
    # c
    return x


def g():  # pragma: no cover
    return 7


def h():
    if (1 ==
            2):
        return 3
    return 4
'''
# SOURCE를 테스트 하나(f만 호출)로 돌렸을 때 coverage.py가 남기는 결과
SOURCE_COV: Final = FileCoverage(
    measured=frozenset({2, 5, 6, 8, 11, 18, 19, 21, 22}),
    executed=frozenset({2, 5, 6, 8, 11, 18}),
)


def _finding(line: int, file: str = "m.py") -> Violation:
    return Violation(f"v{line}", "R-readme-1", file, line, "w", "checker")


def _covered(line: int, source: str | None = SOURCE) -> bool | None:
    cov = CoverageData({"m.py": SOURCE_COV})
    sources = {"m.py": source} if source is not None else None
    return mark_covered([_finding(line)], cov, sources)[0].covered


@pytest.mark.parametrize(
    ("line", "covered"),
    [
        (2, True),  # 실행된 줄
        (19, False),  # 센 줄인데 실행 안 됨
        (9, True),  # 여러 줄 문장의 이어지는 줄 → 문장 첫 줄(8)
        (7, True),  # def 머리의 둘째 줄 → def 줄(6)
        (10, False),  # 함수 몸통 사이의 주석
        (20, False),  # 여러 줄 if 머리 → if 줄(19)이 실행 안 됨
        (15, False),  # pragma: no cover로 빠진 함수 몸통
        (14, False),  # pragma: no cover로 빠진 def
        (1, False),  # 모듈 docstring (센 줄 아님)
        (12, False),  # 빈 줄
        (100, False),  # 파일 밖 줄
    ],
)
def test_line_mapping(line: int, covered: bool) -> None:
    assert _covered(line) is covered


def test_without_source_only_measured_lines_count() -> None:
    assert _covered(2, source=None) is True
    assert _covered(9, source=None) is False


def test_unparsable_source_falls_back_to_measured_lines() -> None:
    assert _covered(9, source="def (:\n") is False
    assert _covered(8, source="def (:\n") is True


def test_decorator_line_is_used_when_def_line_is_not_measured() -> None:
    source = "@dec\ndef f(\n    a,\n):\n    pass\n"
    cov = CoverageData({"m.py": FileCoverage(frozenset({1, 5}), frozenset({1}))})
    assert mark_covered([_finding(3)], cov, {"m.py": source})[0].covered is True


def test_file_not_in_coverage_is_uncovered() -> None:
    cov = CoverageData({"m.py": SOURCE_COV})
    assert mark_covered([_finding(1, file="other.py")], cov)[0].covered is False


def test_missing_coverage_is_unknown() -> None:
    assert mark_covered([_finding(2)], None)[0].covered is None


def test_finding_default_is_unknown_and_order_kept() -> None:
    assert _finding(1).covered is None
    cov = CoverageData({"m.py": SOURCE_COV})
    marked = mark_covered([_finding(19), _finding(2)], cov)
    assert [(f.line, f.covered) for f in marked] == [(19, False), (2, True)]
